function Get-Field {
    param(
        [object]$InputObject,
        [string[]]$Names,
        [object]$Default = $null
    )

    foreach ($name in $Names) {
        $property = $InputObject.PSObject.Properties[$name]
        if ($null -ne $property -and $null -ne $property.Value) {
            return $property.Value
        }
    }

    return $Default
