  50:     public Invoice Reject(string invoiceId, string approver, string reason)
  51:     {
  52:         if (string.IsNullOrWhiteSpace(reason))
  53:         {
  54:             throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
  55:         }
  56: 
  57:         return UpdateAtomically(invoiceId, invoice =>
  58:         {
  59:             EnsurePending(invoice);
  60: 
  61:             invoice.Status = InvoiceStatus.Rejected;
  62:             invoice.DecidedBy = approver;
  63:             invoice.DecidedAt = DateTime.UtcNow;
  64:             invoice.DecisionNote = reason;
  65:         });
  66:     }
  67: 
  68:     private Invoice UpdateAtomically(string invoiceId, Action<Invoice> transition) =>
  69:         _repository.UpdateAtomically(invoiceId, transition)
  70:         ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");
  71: 
  72:     private static void EnsureEligibleRole(string role)
  73:     {
  74:         if (role is not ("Manager" or "Director"))
  75:         {
  76:             throw new InvalidOperationException(
  77:                 $"Role {role} is not permitted to approve invoices.");
  78:         }
  79:     }
  80: 
  81:     private static void EnsurePositiveAmount(Invoice invoice)
  82:     {
  83:         if (invoice.Amount <= 0)
  84:         {
  85:             throw new InvalidOperationException("Invoice amount must be greater than zero.");
  86:         }
  87:     }
  88: 
  89:     private static void ApproveWithinSingleApprovalLimit(Invoice invoice, string approver, string role)
  90:     {
  91:         if (invoice.Approvals.Count != 0)
  92:         {
  93:             throw new InvalidOperationException(
  94:                 "An invoice within the single-approval limit cannot have prior approval records.");
  95:         }
  96: 
  97:         var limit = role == "Manager" ? ManagerApprovalLimit : DirectorApprovalLimit;
  98:         if (invoice.Amount > limit)
  99:         {
  100:             throw new InvalidOperationException(
  101:                 $"{role} approval limit is {FormatAmount(limit)}; invoice amount is {FormatAmount(invoice.Amount)}.");
  102:         }
  103: 
  104:         RecordApproval(invoice, approver, role, 1);
  105:         CompleteApproval(invoice, approver);
  106:     }
  107: 
  108:     private static void ApproveHighValueInvoice(Invoice invoice, string approver, string role)
  109:     {
  110:         if (invoice.DecidedBy is not null || invoice.DecidedAt is not null)
  111:         {
  112:             throw new InvalidOperationException(
  113:                 "A high-value invoice cannot have final decision details before both approvals are recorded.");
  114:         }
  115: 
  116:         if (invoice.Approvals.Count == 0)
  117:         {
  118:             RecordApproval(invoice, approver, role, 1);
  119:             return;
  120:         }
  121: 
  122:         if (invoice.Approvals.Count != 1)
  123:         {
  124:             throw new InvalidOperationException(
  125:                 "A high-value invoice can have only one prior approval while awaiting its second approver.");
  126:         }
  127: 
  128:         var firstApproval = invoice.Approvals[0];
  129:         if (firstApproval.Sequence != 1 || firstApproval.Role is not ("Manager" or "Director"))
  130:         {
  131:             throw new InvalidOperationException(
  132:                 "The existing first approval is invalid; it must be from a Manager or Director.");
  133:         }
  134: 
  135:         if (string.Equals(firstApproval.Username, approver, StringComparison.OrdinalIgnoreCase))
  136:         {
  137:             throw new InvalidOperationException(
  138:                 "The same user cannot provide both approvals for an invoice.");
  139:         }
  140: 
  141:         if (role != "Director")
  142:         {
  143:             throw new InvalidOperationException(
  144:                 "The second approval for an invoice above 500000 must be provided by a Director.");
  145:         }
  146: 
  147:         RecordApproval(invoice, approver, role, 2);
  148:         CompleteApproval(invoice, approver);
  149:     }
  150: 
  151:     private static void RecordApproval(Invoice invoice, string approver, string role, int sequence)
  152:     {
  153:         invoice.Approvals.Add(new InvoiceApproval(approver, role, sequence, DateTime.UtcNow));
  154:     }
  155: 
  156:     private static void CompleteApproval(Invoice invoice, string approver)
  157:     {
  158:         invoice.Status = InvoiceStatus.Approved;
  159:         invoice.DecidedBy = approver;
  160:         invoice.DecidedAt = DateTime.UtcNow;
  161:     }
  162: 
  163:     private static string FormatAmount(decimal amount) =>
  164:         amount.ToString("0.##", System.Globalization.CultureInfo.InvariantCulture);
  165: 
  166:     private static void EnsurePending(Invoice invoice)
  167:     {
